-- ----------------------------
-- Table structure for charity_activity
-- ----------------------------
DROP TABLE IF EXISTS `charity_activity`;
CREATE TABLE `charity_activity`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '活动ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '活动标题',
  `activity_type` enum('offline','donation') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'offline' COMMENT '活动类型: offline-线下活动, donation-公益订单',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '活动状态: 1-待开始, 2-进行中, 3-已结束, 4-已取消',
  `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '封面图片URL',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '活动描述(富文本)',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '活动地点(线下活动专用)',
  `organizer_id` bigint NOT NULL COMMENT '组织者ID(关联用户表)',
  `organizer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '组织者名称',
  `store_id` bigint NULL DEFAULT NULL COMMENT '参与店铺ID',
  `store_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '参与店铺名称',
  `max_participants` int NULL DEFAULT 0 COMMENT '最大参与人数(0表示不限)',
  `current_participants` int NULL DEFAULT 0 COMMENT '当前参与人数',
  `donation_rate` decimal(5, 2) NULL DEFAULT 5.00 COMMENT '捐赠比例(%)',
  `total_donation` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '累计捐赠金额',
  `views_count` int NULL DEFAULT 0 COMMENT '浏览数',
  `likes_count` int NULL DEFAULT 0 COMMENT '点赞数',
  `collects_count` int NULL DEFAULT 0 COMMENT '收藏数',
  `comments_count` int NULL DEFAULT 0 COMMENT '评论数',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status_type`(`status` ASC, `activity_type` ASC) USING BTREE,
  INDEX `idx_organizer`(`organizer_id` ASC) USING BTREE,
  INDEX `idx_time`(`start_time` ASC, `end_time` ASC) USING BTREE,
  INDEX `idx_search`(`title` ASC, `status` ASC, `activity_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '公益活动表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of charity_activity
-- ----------------------------

