DROP TABLE IF EXISTS `charity_goods`;
CREATE TABLE `charity_goods`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '商品ID',
  `activity_id` bigint NOT NULL COMMENT '活动ID',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商品名称',
  `image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商品图片',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '商品描述',
  `price` decimal(10, 2) NOT NULL COMMENT '商品价格',
  `stock` int NULL DEFAULT 0 COMMENT '库存数量',
  `sales` int NULL DEFAULT 0 COMMENT '销量',
  `donation_amount` decimal(10, 2) NOT NULL COMMENT '单件捐赠金额(price * donation_rate)',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 1-上架, 2-下架, 3-售罄',
